input.content:
:root{
  --leaf:#a4ef68;
  --leaf-deep:#5cc63b;
  --leaf-dark:#2e7a26;
  --gold:#ffd45e;
  --cream:#f2ffdc;
  --ink:#071611;
  --panel:rgba(6,26,21,.86);
  --line:rgba(190,255,150,.28);
  --shadow:0 26px 70px rgba(0,0,0,.55);
  --font:"Trebuchet MS","Segoe UI",system-ui,-apple-system,sans-serif;
}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent;}
html,body{height:100%;}
body{
  margin:0;overflow:hidden;color:var(--cream);font-family:var(--font);
  background:
    radial-gradient(1100px 720px at 50% 12%, #17483b 0%, #0a2119 48%, #030a07 100%);
  user-select:none;-webkit-user-select:none;
  touch-action:none;
}
#app{position:fixed;inset:0;display:grid;place-items:center;}
#stage{
  position:relative;
  width:min(100vw, calc(100vh * 5 / 3));
  height:min(100vh, calc(100vw * 3 / 5));
  overflow:hidden;
  background:#061a16;
  box-shadow:0 0 0 1px rgba(160,255,120,.14), 0 40px 120px rgba(0,0,0,.7);
}
#stage::after{
  content:"";position:absolute;inset:0;pointer-events:none;z-index:3;
  background:radial-gradient(120% 100% at 50% 45%, transparent 55%, rgba(0,0,0,.35) 100%);
}
canvas{display:block;width:100%;height:100%;}

/* ---------- HUD buttons ---------- */
.hud-buttons{
  position:absolute;z-index:6;display:flex;gap:8px;
  top:max(8px, env(safe-area-inset-top));right:max(8px, env(safe-area-inset-right));
}
.round{
  appearance:none;width:clamp(34px,5.4vmin,44px);height:clamp(34px,5.4vmin,44px);
  display:grid;place-items:center;padding:0;cursor:pointer;color:#dfffc4;
  background:rgba(5,25,20,.62);border:1px solid var(--line);border-radius:50%;
  backdrop-filter:blur(5px);transition:transform .12s, background .2s;
}
.round:hover{background:rgba(20,70,48,.8);}
.round:active{transform:scale(.92);}
.round svg{width:56%;height:56%;}
.round .ico-muted{display:none;}
body.muted .round .ico-sound{display:none;}
body.muted .round .ico-muted{display:block;}

/* ---------- Overlay / cards ---------- */
.overlay{
  position:absolute;inset:0;z-index:8;display:grid;place-items:center;
  padding:clamp(10px,3.2vmin,30px);
  background:rgba(2,10,8,.5);backdrop-filter:blur(7px);
  transition:opacity .28s ease, visibility .28s;
}
.overlay.is-hidden{opacity:0;visibility:hidden;pointer-events:none;}
.card{
  width:min(600px,100%);max-height:100%;overflow:auto;overscroll-behavior:contain;
  padding:clamp(18px,3.4vmin,34px) clamp(16px,3.2vmin,30px);
  text-align:center;
  background:
    radial-gradient(90% 70% at 50% 0%, rgba(96,200,110,.16), transparent 70%),
    linear-gradient(180deg, rgba(13,45,36,.97), rgba(5,22,18,.98));
  border:2px solid rgba(150,240,110,.3);
  border-radius:clamp(18px,3vmin,26px);
  box-shadow:var(--shadow), inset 0 1px 0 rgba(255,255,255,.09);
  animation:pop .32s cubic-bezier(.2,1.3,.4,1);
}
@keyframes pop{from{transform:translateY(14px) scale(.97);opacity:0}to{transform:none;opacity:1}}
.eyebrow{
  font-size:clamp(9px,1.55vmin,12px);font-weight:800;letter-spacing:.28em;
  text-transform:uppercase;color:#8fe073;opacity:.95;margin:0 0 6px;
}
.logo{
  margin:0;font-weight:900;line-height:.86;letter-spacing:.01em;
  font-size:clamp(42px,10vmin,78px);color:#d3ff96;
  text-shadow:0 4px 0 #276b2b, 0 12px 34px rgba(120,255,110,.28);
}
.logo span{
  display:block;font-size:.52em;letter-spacing:.22em;color:var(--gold);
  text-shadow:0 3px 0 #7a4c15, 0 10px 26px rgba(255,190,60,.25);
  margin-top:.22em;padding-left:.22em;
}
h2{
  margin:.1em 0 .25em;font-size:clamp(26px,5.4vmin,42px);line-height:1;
  color:#e6ffbe;text-shadow:0 3px 0 #245e29, 0 10px 26px rgba(0,0,0,.45);
}
.lead{
  margin:.7em auto .2em;max-width:44ch;color:#c7e8bd;
  font-size:clamp(13px,2.05vmin,16px);line-height:1.5;
}
.row{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin-top:clamp(14px,2.6vmin,22px);}
.btn{
  appearance:none;border:0;cursor:pointer;font-family:inherit;font-weight:900;
  text-transform:uppercase;letter-spacing:.06em;color:#12310f;
  font-size:clamp(14px,2.2vmin,18px);padding:.82em 1.45em;border-radius:16px;
  background:linear-gradient(180deg,#c6f97c,#6fd143);
  box-shadow:0 6px 0 var(--leaf-dark), 0 14px 26px rgba(0,0,0,.38);
  transition:transform .1s, box-shadow .1s, filter .2s;
  display:inline-flex;align-items:center;gap:.5em;
}
.btn:hover{filter:brightness(1.06);}
.btn:active{transform:translateY(4px);box-shadow:0 2px 0 var(--leaf-dark), 0 6px 14px rgba(0,0,0,.35);}
.btn.secondary{
  color:#163d16;background:linear-gradient(180deg,#f4ffe2,#c8e0ac);
  box-shadow:0 6px 0 #7e9a6a, 0 14px 26px rgba(0,0,0,.35);
}
.btn.ghost{
  background:transparent;color:#d6f8c3;border:2px solid rgba(190,255,150,.28);
  box-shadow:none;font-weight:800;
}
.btn.ghost:active{transform:translateY(2px);}
.btn:disabled{opacity:.45;cursor:not-allowed;filter:grayscale(.4);}

.levels{margin-top:clamp(14px,2.8vmin,22px);}
.levels>span{
  display:block;font-size:10px;letter-spacing:.24em;text-transform:uppercase;
  color:#87b37a;font-weight:800;margin-bottom:8px;
}
.level-chips{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;}
.chip{
  appearance:none;cursor:pointer;font-family:inherit;font-weight:900;font-size:13px;
  min-width:clamp(40px,7vmin,54px);height:clamp(34px,6vmin,42px);padding:0 .8em;
  border-radius:12px;color:#c9e8bb;background:rgba(255,255,255,.05);
  border:1.5px solid rgba(190,255,150,.2);transition:.15s;
}
.chip:hover{border-color:rgba(190,255,150,.55);color:#efffd9;}
.chip.is-active{
  color:#0c2a0c;background:linear-gradient(180deg,#d5ff90,#8ee05a);
  border-color:#c9ff8f;box-shadow:0 0 18px rgba(150,255,120,.3);
}
.chip.is-locked{opacity:.4;cursor:not-allowed;}

.keys{
  margin-top:clamp(14px,2.6vmin,20px);display:flex;gap:6px 12px;justify-content:center;
  flex-wrap:wrap;font-size:clamp(10px,1.6vmin,12.5px);color:#9dbf93;
}
.keys span{display:inline-flex;align-items:center;gap:5px;white-space:nowrap;}
kbd{
  font-family:inherit;font-weight:800;font-size:.94em;color:#eaffd7;
  background:rgba(255,255,255,.08);border:1px solid rgba(220,255,190,.22);
  border-bottom-width:2px;border-radius:6px;padding:2px 6px;min-width:20px;
}
.best{
  margin-top:12px;font-size:clamp(11px,1.7vmin,13px);letter-spacing:.12em;
  text-transform:uppercase;color:#7ea474;font-weight:700;
}
.best b{color:var(--gold);letter-spacing:0;}
.stats{
  display:grid;grid-template-columns:repeat(4,1fr);gap:8px;
  margin:clamp(14px,2.6vmin,22px) 0 4px;
}
.stats>div{
  background:rgba(255,255,255,.045);border:1px solid rgba(190,255,150,.13);
  border-radius:14px;padding:clamp(8px,1.6vmin,12px) 4px;
}
.stats b{display:block;font-size:clamp(17px,3vmin,23px);color:var(--gold);line-height:1.1;}
.stats span{
  display:block;margin-top:3px;font-size:clamp(8px,1.35vmin,10px);
  letter-spacing:.13em;text-transform:uppercase;color:#8fb483;font-weight:800;
}
.tip{
  margin:10px 0 0;font-size:clamp(10px,1.6vmin,12.5px);color:#86a97e;
  font-style:italic;
}
@media (max-height:520px){
  .card{padding:14px 18px;}
  .logo{font-size:clamp(30px,8vmin,48px);}
  .lead{display:none;}
  .keys{margin-top:10px;}
  .stats{margin:10px 0 2px;}
  .tip{display:none;}
}
@media (max-width:560px){
  .stats{grid-template-columns:repeat(2,1fr);}
}

/* ---------- Toast ---------- */
.toast{
  position:absolute;z-index:7;left:50%;top:13%;
  transform:translate(-50%,-10px);opacity:0;pointer-events:none;
  padding:.55em 1.1em;border-radius:999px;white-space:nowrap;
  background:rgba(5,30,23,.86);border:1px solid rgba(190,255,150,.4);
  color:#e9ffcb;font-weight:800;font-size:clamp(11px,1.75vmin,15px);
  letter-spacing:.04em;box-shadow:0 10px 30px rgba(0,0,0,.4);
  transition:opacity .22s, transform .22s;
}
.toast.show{opacity:1;transform:translate(-50%,0);}

/* ---------- Touch controls ---------- */
.touch{
  position:fixed;inset:auto 0 0 0;z-index:9;
  display:none;justify-content:space-between;align-items:flex-end;
  padding:0 max(14px, env(safe-area-inset-right)) max(14px, env(safe-area-inset-bottom)) max(14px, env(safe-area-inset-left));
  pointer-events:none;
  gap:16px;
}
body.touch-mode .touch{display:flex;}
body.in-menu .touch{display:none;}
.touch-group{display:flex;align-items:flex-end;gap:clamp(8px,1.8vmin,14px);pointer-events:none;}
.pad{
  pointer-events:auto;touch-action:none;appearance:none;border-radius:50%;
  width:clamp(56px,12.5vmin,82px);height:clamp(56px,12.5vmin,82px);
  display:grid;place-items:center;color:#eeffd8;cursor:pointer;
  border:2px solid rgba(220,255,190,.34);
  background:radial-gradient(circle at 34% 28%, rgba(180,255,140,.32), rgba(8,36,27,.6));
  box-shadow:0 10px 26px rgba(0,0,0,.42), inset 0 1px 0 rgba(255,255,255,.14);
  backdrop-filter:blur(3px);transition:transform .08s, background .15s;
  font-family:inherit;font-weight:900;
}
.pad svg{width:46%;height:46%;}
.pad.pressed{transform:scale(.93);background:radial-gradient(circle at 34% 28%, rgba(210,255,170,.55), rgba(20,70,45,.7));}
.action-jump{width:clamp(70px,15vmin,96px);height:clamp(70px,15vmin,96px);}
.action-tongue{width:clamp(50px,10.5vmin,66px);height:clamp(50px,10.5vmin,66px);}
.pad-label{font-size:clamp(8px,1.6vmin,10.5px);letter-spacing:.09em;}
@media (hover:hover) and (pointer:fine){
  body.touch-mode .touch{display:none;}
}

/* ============================================================
   SAPO SALVAJE — niveles
   Construidos con un pequeño "level builder" para mantenerlos
   legibles y fáciles de retocar.
   ============================================================ */
(function () {
  'use strict';

  const T = 48;
  const ROWS = 12;

  const THEMES = [
    { // 1 · atardecer en el pantano
      name: 'luna',
      sky: ['#0a2831', '#1d5a54', '#8fc48a'],
      sun: '#ffecad',
      sunGlow: 'rgba(255,226,140,0.35)',
      hillFar: '#174a44',
      hillMid: '#103a35',
      hillNear: '#0a2a26',
      tree: '#08211e',
      treeLeaf: '#123a31',
      vine: '#1c4a3a',
      water: '#0e3b45',
      waterDeep: '#072730',
      waterHi: '#63e0c2',
      mist: 'rgba(190,255,220,0.055)',
      grassTop: '#7fd257',
      grassDark: '#3e9439',
      dirt: '#63452f',
      dirtDark: '#49301f',
      dirtLight: '#7a5639',
      brick: '#b4643c',
      brickDark: '#7a3f25',
      stone: '#5f7a6a',
      accent: '#ffd76e',
      mote: '#ffe9a3'
    },
    { // 2 · mañana entre raíces
      name: 'raices',
      sky: ['#08271f', '#1e5c3f', '#a9d693'],
      sun: '#fff5c2',
      sunGlow: 'rgba(255,246,190,0.32)',
      hillFar: '#1a5138',
      hillMid: '#12402c',
      hillNear: '#0b2d20',
      tree: '#082218',
      treeLeaf: '#14412c',
      vine: '#265b3b',
      water: '#0f3f43',
      waterDeep: '#082a2d',
      waterHi: '#74e6c0',
      mist: 'rgba(210,255,220,0.06)',
      grassTop: '#8ade5a',
      grassDark: '#469c38',
      dirt: '#5c412d',
      dirtDark: '#432c1c',
      dirtLight: '#73563a',
      brick: '#a85f3c',
      brickDark: '#734026',
      stone: '#5a7568',
      accent: '#ffdd7a',
      mote: '#f7ffc9'
    },
    { // 3 · fuego en el manglar
      name: 'manglar',
      sky: ['#241228', '#6d3547', '#e2a06e'],
      sun: '#ffd08a',
      sunGlow: 'rgba(255,180,100,0.36)',
      hillFar: '#4b2a3f',
      hillMid: '#3a2033',
      hillNear: '#261426',
      tree: '#1c0f1c',
      treeLeaf: '#38203a',
      vine: '#4a2848',
      water: '#33223d',
      waterDeep: '#1d1329',
      waterHi: '#ffb36b',
      mist: 'rgba(255,205,160,0.07)',
      grassTop: '#c6d95c',
      grassDark: '#6f8c33',
      dirt: '#5c3b36',
      dirtDark: '#40262a',
      dirtLight: '#75503f',
      brick: '#b96548',
      brickDark: '#7c3f2e',
      stone: '#6d5f6a',
      accent: '#ffca74',
      mote: '#ffd9a0'
    }
  ];

  class Builder {
    constructor(cfg) {
      this.name = cfg.name;
      this.subtitle = cfg.subtitle || '';
      this.width = cfg.width;
      this.time = cfg.time || 240;
      this.theme = cfg.theme;
      this.grid = Array.from({ length: ROWS }, () => new Array(this.width).fill('.'));
      this.coins = [];
      this.enemies = [];
      this.items = [];
      this.checkpoints = [];
      this.movers = [];
      this.spawn = { x: 3 * T + T / 2, y: 10 * T - 1 };
      this.goal = { x: (this.width - 8) * T, y: 10 * T };
    }

    set(cx, cy, ch) {
      if (cx >= 0 && cx < this.width && cy >= 0 && cy < ROWS) this.grid[cy][cx] = ch;
      return this;
    }
    fill(x0, y0, x1, y1, ch) {
      for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) this.set(x, y, ch);
      return this;
    }
    ground(x0, x1, top = 10) { return this.fill(x0, top, x1, ROWS - 1, '#'); }
    brick(x, y, n = 1) { for (let i = 0; i < n; i++) this.set(x + i, y, 'B'); return this; }
    q(x, y) { return this.set(x, y, '?'); }
    wood(x, y, n = 1) { for (let i = 0; i < n; i++) this.set(x + i, y, '='); return this; }
    plat(x, y, n = 1) { for (let i = 0; i < n; i++) this.set(x + i, y, '-'); return this; }
    spikes(x, y, n = 1) { for (let i = 0; i < n; i++) this.set(x + i, y, '^'); return this; }
    pipe(x, top) { return this.fill(x, top, x + 1, 9, 'P'); }

    coin(cx, cy) { this.coins.push({ cx, cy }); return this; }
    coinRow(cx, cy, n, step = 1) {
      for (let i = 0; i < n; i++) this.coin(cx + i * step, cy);
      return this;
    }
    coinArc(cx, cy, n) {
      for (let i = 0; i < n; i++) {
        const t = n > 1 ? i / (n - 1) : 0;
        this.coin(cx + i, cy - Math.round(Math.sin(t * Math.PI) * 1.7));
      }
      return this;
    }
    snail(cx, row = 10) { this.enemies.push({ type: 'snail', cx, row }); return this; }
    fly(cx, row = 6, range = 2) { this.enemies.push({ type: 'fly', cx, row, range }); return this; }
    urchin(cx, row = 10) { this.enemies.push({ type: 'urchin', cx, row }); return this; }
    heart(cx, row = 8) { this.items.push({ type: 'heart', cx, row }); return this; }
    checkpoint(cx, row = 10) { this.checkpoints.push({ cx, row }); return this; }
    spawnAt(cx, row = 10) { this.spawn = { x: cx * T + T / 2, y: row * T - 1 }; return this; }
    goalAt(cx, row = 10) { this.goal = { x: cx * T + T / 2, y: row * T }; return this; }
    mover(cx, row, tilesWide, axis, tilesDist, rate = 0.8) {
      this.movers.push({
        x: cx * T, y: row * T, w: tilesWide * T, h: 18,
        axis, dist: tilesDist * T, rate
      });
      return this;
    }

    build() {
      // Rellena con agua cualquier hueco en las dos filas del suelo.
      for (let x = 0; x < this.width; x++) {
        if (this.grid[10][x] === '.' && this.grid[11][x] === '.') {
          this.grid[10][x] = '~';
          this.grid[11][x] = '~';
        }
      }
      return {
        name: this.name,
        subtitle: this.subtitle,
        width: this.width,
        height: ROWS,
        time: this.time,
        theme: this.theme,
        grid: this.grid,
        coins: this.coins.map(c => ({ x: c.cx * T + T / 2, y: c.cy * T + T / 2 })),
        enemies: this.enemies.map(e => ({
          type: e.type,
          x: e.cx * T + T / 2,
          y: e.row * T + (e.type === 'fly' ? T / 2 : 0),
          row: e.row,
          range: (e.range || 2) * T
        })),
        items: this.items.map(i => ({ type: i.type, x: i.cx * T + T / 2, y: i.row * T + T / 2 })),
        checkpoints: this.checkpoints.map(c => ({ x: c.cx * T + T / 2, y: c.row * T })),
        movers: this.movers,
        spawn: this.spawn,
        goal: this.goal
      };
    }
  }

  // ============================================================
  // NIVEL 1 — Pantano de la Luna
  // ============================================================
  const L1 = (() => {
    const b = new Builder({ name: 'Pantano de la Luna', subtitle: 'Nivel 1', width: 134, time: 240, theme: THEMES[0] });
    b.spawnAt(3);
    b.ground(0, 36);
    b.ground(40, 70);
    b.ground(75, 133);

    b.coinRow(5, 8, 4);
    b.snail(11);

    b.brick(15, 7, 5); b.q(17, 7);
    b.coinRow(15, 5, 5);
    b.snail(22);

    b.pipe(26, 8);
    b.plat(31, 7, 3);
    b.coinRow(31, 6, 3);
    b.snail(33);

    b.coinArc(35, 7, 6);            // arco sobre el primer hueco

    b.fly(45, 6, 2.2);
    b.snail(48);
    b.coinRow(44, 8, 3);

    b.brick(52, 7, 4); b.q(53, 7);
    b.coinRow(52, 5, 4);
    b.snail(58);

    b.checkpoint(60);
    b.snail(65);
    b.plat(72, 9, 2);               // piedra de paso en el segundo hueco
    b.coinRow(71, 7, 4);

    b.spikes(80, 9, 2);
    b.coinRow(79, 7, 4);
    b.snail(86);
    b.fly(91, 6, 2.4);

    b.brick(94, 7, 6); b.q(96, 7);
    b.coinRow(94, 5, 6);
    b.snail(102);
    b.coinRow(104, 8, 3);

    // Escalera final hasta la flor de loto
    b.wood(106, 9, 2);
    b.wood(109, 8, 2);
    b.wood(112, 7, 2);
    b.wood(116, 6, 10);
    b.coinRow(117, 5, 6);
    b.fly(120, 3, 1.6);
    b.goalAt(122, 6);

    return b.build();
  })();

  // ============================================================
  // NIVEL 2 — Raíces Colgantes
  // ============================================================
  const L2 = (() => {
    const b = new Builder({ name: 'Raíces Colgantes', subtitle: 'Nivel 2', width: 150, time: 270, theme: THEMES[1] });
    b.spawnAt(3);
    b.ground(0, 18);
    b.ground(28, 50);
    b.ground(59, 88);
    b.ground(98, 149);

    b.snail(10);
    b.brick(13, 7, 4); b.q(15, 7);
    b.coinRow(13, 5, 4);

    // hueco 19-27: plataforma móvil
    b.mover(19, 9, 3, 'x', 6, 0.75);
    b.coinArc(19, 6, 9);
    b.fly(22, 4, 2.2);

    b.snail(32);
    b.spikes(36, 9, 3);
    b.coinRow(36, 7, 3);
    b.urchin(43);
    b.checkpoint(46);
    b.snail(48);

    // hueco 51-58: dos plataformas de madera
    b.plat(52, 8, 2);
    b.plat(56, 7, 2);
    b.coinRow(52, 7, 2);
    b.coinRow(56, 6, 2);
    b.fly(55, 5, 1.8);

    b.snail(61);
    b.brick(63, 7, 4); b.q(64, 7);
    b.coinRow(63, 5, 4);
    b.spikes(68, 9, 3);
    b.heart(73, 8);
    b.checkpoint(76);
    b.urchin(80);
    b.fly(85, 5, 2.4);

    // hueco 89-97: plataforma vertical
    b.mover(91, 9, 4, 'y', 4, 0.7);
    b.coinArc(90, 7, 8);

    b.snail(101);
    b.brick(105, 7, 5); b.q(107, 7);
    b.coinRow(105, 5, 5);
    b.checkpoint(112);
    b.urchin(117);
    b.spikes(120, 9, 2);
    b.coinRow(119, 7, 4);
    b.snail(125);
    b.fly(129, 5, 2);
    b.brick(132, 7, 4); b.q(134, 7);
    b.coinRow(132, 5, 4);

    b.wood(136, 9, 2);
    b.wood(139, 8, 8);
    b.coinRow(140, 7, 4);
    b.goalAt(143, 8);

    return b.build();
  })();

  // ============================================================
  // NIVEL 3 — Corazón del Manglar
  // ============================================================
